const ctx = GameAPI.ctx;
const canvas = GameAPI.canvas;
const players = GameAPI.players;

// ── Constants ──
const PLAYER_SPD_SEC = 30;
const BULLET_SPEED = 4;
const EBULLET_SPEED = 2.5;
const BASE_ENEMY_SPD = 0.45;
const SHOOT_CD = 10;
const INVINCIBLE = 20;
const ENEMY_COLS = 8;
const ENEMY_ROWS = 4;
const ENEMY_SX = 10;
const ENEMY_SY = 7;
const ENEMY_X0 = 10;
const ENEMY_Y0 = 12;
const PLAYER_Y = 88;
const ROW_CFG = [['\u{1F480}', 50], ['\u{1F47E}', 30], ['\u{1F916}', 10], ['\u{1F916}', 10]];
const SHIP_EMOJIS = ['\u{1F680}', '\u{1F6F8}', '\u{2708}\u{FE0F}', '\u{1F4DA}'];

// ── Game State ──
let active = true;
let score = 0;
let lives = 5;
let bullets = [];
let ebullets = [];
let enemies = [];
let edir = 1;
let espd = BASE_ENEMY_SPD;
let tick = 0;
let over = false;
let won = false;
let stars = [];
let tickAcc = 0;
let lastTs = 0;
const TICK_MS = 67;
let inv = 0;

// Per-player ships: playerId \u2192 { x, dir, cooldown, color }
const ships = new Map();
let shipCounter = 0;

function getShip(playerId) {
  if (!ships.has(playerId)) {
    const count = shipCounter++;
    const spacing = 80 / Math.max([...players.keys()].length, 1);
    ships.set(playerId, {
      x: 10 + count * spacing,
      dir: 0,
      cooldown: 0,
      emoji: SHIP_EMOJIS[count % SHIP_EMOJIS.length]
    });
  }
  return ships.get(playerId);
}

// Generate stars
for (let i = 0; i < 50; i++) {
  stars.push({
    x: Math.random() * canvas.width,
    y: Math.random() * canvas.height,
    r: Math.random() * 1.2 + 0.3,
    a: Math.random() * 0.5 + 0.15
  });
}

// Init enemies
for (let r = 0; r < ENEMY_ROWS; r++) {
  for (let c = 0; c < ENEMY_COLS; c++) {
    enemies.push({
      x: ENEMY_X0 + c * ENEMY_SX,
      y: ENEMY_Y0 + r * ENEMY_SY,
      alive: true,
      pts: ROW_CFG[r][1],
      emoji: ROW_CFG[r][0]
    });
  }
}

// ── Input ──
GameAPI.onInput((playerId, key, state, p) => {
  if (!active) return;
  const ship = getShip(playerId);
  if (state === 'down') {
    if (key === 'left' || key === 'up-left' || key === 'down-left') ship.dir = -1;
    else if (key === 'right' || key === 'up-right' || key === 'down-right') ship.dir = 1;
    else if (key === 'btn1') {
      if (ship.cooldown <= 0 && !over) {
        bullets.push({ x: ship.x, y: PLAYER_Y - 3 });
        ship.cooldown = SHOOT_CD;
      }
    }
  } else {
    const isL = key === 'left' || key === 'up-left' || key === 'down-left';
    const isR = key === 'right' || key === 'up-right' || key === 'down-right';
    if (isL && ship.dir === -1) ship.dir = 0;
    else if (isR && ship.dir === 1) ship.dir = 0;
  }
});

// ── Game Logic ──
function moveEnemies() {
  const alive = enemies.filter(e => e.alive);
  if (!alive.length) return;
  let minX = Infinity, maxX = -Infinity;
  for (const e of alive) {
    if (e.x < minX) minX = e.x;
    if (e.x > maxX) maxX = e.x;
  }
  if ((edir === 1 && maxX >= 92) || (edir === -1 && minX <= 8)) {
    edir *= -1;
    for (const e of alive) e.y += 3.5;
  }
  for (const e of alive) e.x += espd * edir;
}

function enemyShoot() {
  const alive = enemies.filter(e => e.alive);
  if (!alive.length) return;
  const bottom = new Map();
  for (const e of alive) {
    const col = Math.round(e.x);
    if (!bottom.has(col) || e.y > bottom.get(col).y) bottom.set(col, e);
  }
  const chance = 0.007 + (1 - alive.length / enemies.length) * 0.02;
  for (const e of bottom.values()) {
    if (Math.random() < chance) ebullets.push({ x: e.x, y: e.y + 3 });
  }
}

function hitEnemies() {
  bullets = bullets.filter(b => {
    for (const e of enemies) {
      if (!e.alive) continue;
      if (Math.abs(b.x - e.x) < 3.5 && Math.abs(b.y - e.y) < 3.5) {
        e.alive = false;
        score += e.pts;
        return false;
      }
    }
    return true;
  });
  const alive = enemies.filter(e => e.alive).length;
  espd = BASE_ENEMY_SPD + (1 - alive / enemies.length) * 1.4;
}

function hitPlayers() {
  if (inv > 0) return;
  ebullets = ebullets.filter(b => {
    for (const ship of ships.values()) {
      if (Math.abs(b.x - ship.x) < 4 && Math.abs(b.y - PLAYER_Y) < 5) {
        lives--;
        inv = INVINCIBLE;
        if (lives <= 0) { active = false; over = true; won = false; }
        return false;
      }
    }
    return true;
  });
}

function checkEnd() {
  if (enemies.every(e => !e.alive)) { active = false; over = true; won = true; }
  if (enemies.some(e => e.alive && e.y >= PLAYER_Y - 4)) { active = false; over = true; won = false; }
}

// ── Render ──
function toX(pct) { return pct / 100 * canvas.width; }
function toY(pct) { return pct / 100 * canvas.height; }
function toS(pct) { return pct / 100 * Math.min(canvas.width, canvas.height); }

function drawFrame(ts) {
  if (!active && over) { drawGameOver(); return; }

  // Smooth player movement every frame
  const dt = lastTs ? (ts - lastTs) / 1000 : 0;
  for (const ship of ships.values()) {
    ship.x += ship.dir * PLAYER_SPD_SEC * dt;
    ship.x = Math.max(5, Math.min(95, ship.x));
  }

  // Game logic at fixed tick rate
  if (lastTs) tickAcc += ts - lastTs;
  lastTs = ts;
  while (tickAcc >= TICK_MS) {
    tickAcc -= TICK_MS;
    tick++;

    bullets = bullets.filter(b => { b.y -= BULLET_SPEED; return b.y > 0; });
    ebullets = ebullets.filter(b => { b.y += EBULLET_SPEED; return b.y < 100; });

    moveEnemies();
    enemyShoot();

    for (const ship of ships.values()) { if (ship.cooldown > 0) ship.cooldown--; }
    if (inv > 0) inv--;

    hitEnemies();
    hitPlayers();
    checkEnd();
  }

  const W = canvas.width, H = canvas.height;

  ctx.fillStyle = '#05051a';
  ctx.fillRect(0, 0, W, H);

  // Stars
  for (const s of stars) {
    ctx.fillStyle = `rgba(255,255,255,${s.a})`;
    ctx.beginPath();
    ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
    ctx.fill();
  }

  // HUD - score
  ctx.fillStyle = '#ffdd44';
  ctx.font = `700 ${toS(2.8)}px monospace`;
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.shadowColor = 'rgba(255,221,68,0.4)';
  ctx.shadowBlur = 10;
  ctx.fillText('\u{5F97}\u{5206}\u{FF1A}' + score, toX(3), toY(2));
  ctx.shadowBlur = 0;

  // HUD - lives
  ctx.font = `${toS(2.8)}px serif`;
  ctx.textAlign = 'right';
  for (let i = 0; i < lives; i++) {
    ctx.fillText('\u{2764}\u{FE0F}', toX(97) - i * toS(3.5), toY(2));
  }

  // Enemies
  ctx.font = `${toS(3.2)}px serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  for (const e of enemies) {
    if (!e.alive) continue;
    ctx.fillText(e.emoji, toX(e.x), toY(e.y));
  }

  // Player bullets
  for (const b of bullets) {
    const bx = toX(b.x), by = toY(b.y);
    const bw = Math.max(W * 0.004, 3);
    const bh = Math.max(H * 0.016, 10);
    const grad = ctx.createLinearGradient(bx, by + bh, bx, by);
    grad.addColorStop(0, '#88ff44');
    grad.addColorStop(1, '#44ff88');
    ctx.save();
    ctx.shadowColor = '#88ff44';
    ctx.shadowBlur = 6;
    ctx.fillStyle = grad;
    ctx.fillRect(bx - bw / 2, by - bh, bw, bh);
    ctx.restore();
  }

  // Enemy bullets
  for (const b of ebullets) {
    const bx = toX(b.x), by = toY(b.y);
    const bw = Math.max(W * 0.004, 3);
    const bh = Math.max(H * 0.012, 8);
    const grad = ctx.createLinearGradient(bx, by, bx, by + bh);
    grad.addColorStop(0, '#ff4466');
    grad.addColorStop(1, '#ff2244');
    ctx.save();
    ctx.shadowColor = '#ff4466';
    ctx.shadowBlur = 6;
    ctx.fillStyle = grad;
    ctx.fillRect(bx - bw / 2, by, bw, bh);
    ctx.restore();
  }

  // All player ships
  const pVisible = inv === 0 || tick % 4 < 2;
  ctx.font = `${toS(4)}px serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  for (const [pid, ship] of ships) {
    const pp = players.get(pid);
    if (pVisible) {
      ctx.save();
      if (pp) { ctx.shadowColor = pp.color; ctx.shadowBlur = 8; }
      ctx.fillText(ship.emoji, toX(ship.x), toY(PLAYER_Y));
      ctx.restore();
    }
    // Player name below ship
    if (pp) {
      ctx.font = `600 ${toS(1.6)}px sans-serif`;
      ctx.fillStyle = pp.color;
      ctx.fillText(pp.name, toX(ship.x), toY(PLAYER_Y + 5));
      ctx.font = `${toS(4)}px serif`;
    }
  }

  // Ready overlay
  if (tick < 22) {
    ctx.fillStyle = 'rgba(0,0,20,0.8)';
    ctx.fillRect(0, 0, W, H);
    ctx.font = `700 ${toS(6)}px sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = '#fff';
    ctx.fillText('\u{1F680}', W / 2, H / 2 - toS(4));
    ctx.font = `700 ${toS(3)}px sans-serif`;
    ctx.fillStyle = '#aaaaff';
    ctx.fillText('\u{6E96}\u{5099}\u{958B}\u{59CB}\u{FF01}', W / 2, H / 2 + toS(2));
  }
}

function drawGameOver() {
  const W = canvas.width, H = canvas.height;
  ctx.fillStyle = 'rgba(0,0,20,0.78)';
  ctx.fillRect(0, 0, W, H);
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.font = `700 ${toS(7)}px sans-serif`;
  ctx.fillStyle = '#fff';
  ctx.fillText(won ? '\u{1F389} \u{52DD}\u{5229}\u{FF01}' : '\u{1F480} \u{5931}\u{6557}\u{FF01}', W / 2, H / 2 - toS(4));
  ctx.font = `700 ${toS(4)}px sans-serif`;
  ctx.fillStyle = '#ffdd44';
  ctx.fillText('\u{5F97}\u{5206}\u{FF1A}' + score, W / 2, H / 2 + toS(1));
  ctx.font = `700 ${toS(2.5)}px sans-serif`;
  ctx.fillStyle = '#7777aa';
  ctx.fillText('\u{7B49}\u{5F85}\u{4E3B}\u{6301}\u{4EBA}\u{63A8}\u{9032}\u{4E0B}\u{4E00}\u{968E}\u{6BB5}', W / 2, H / 2 + toS(5));
}

GameAPI.update(ts => drawFrame(ts));
